expression:
recode_values(
  local({
    e <- coalesce(as.numeric(BDC06E00), as.numeric(CDC06E00), as.numeric(DDC06E00), as.numeric(FDCE0600))
    k <- !is.na(e)
    e[k][match(participant_id, participant_id[k])]
  }),
  1 ~ "Non-minority",
  c(2, 3, 4, 5, 6) ~ "Minority",
  default = "Unknown"
)

local({
  uk <- cbind(as.numeric(respondent_born_uk), as.numeric(respondent_born_uk_PARTNER))
  case_when(
    rowSums(uk == 1, na.rm = TRUE) > 0 ~ "Native",
    rowSums(uk == 2, na.rm = TRUE) > 0 ~ "Second-generation",
    .default = "Unknown"
  )
})

local({
  items <- cbind(
    coalesce(as.numeric(ECQ26X00), as.numeric(FCSTOL00), as.numeric(GCSTOL00)),
    coalesce(as.numeric(FCSTLN00), as.numeric(GCSTLN00)),
    as.numeric(GCJYRD00)
  )
  case_when(rowSums(items == 1, na.rm = TRUE) > 0 ~ "TRUE", items[, 1] == 2 ~ "FALSE", .default = NA_character_)
})

local({
  graffiti <- coalesce(as.numeric(ECQ27X00), as.numeric(FCSPRY00), as.numeric(GCSPRY00))
  damage <- coalesce(as.numeric(ECQ28X00), as.numeric(FCDAMG00), as.numeric(GCDAMG00))
  case_when(graffiti == 1 | damage == 1 ~ "TRUE", graffiti == 2 & damage == 2 ~ "FALSE", .default = NA_character_)
})
